/**
 * Personal photos for the Home page gallery and the portrait images used across the site.
 * Image files and dimensions are generated by `npm run photos` (scripts/optimize-photos.mjs)
 * from the source photos in assets-src/photos; this file adds captions and ordering.
 */
import generatedPhotos from './photos.generated.json';

const getPhoto = (slug) => {
  const photo = generatedPhotos[slug];
  if (!photo) {
    throw new Error(`Photo "${slug}" not found. Add it to assets-src/photos and run npm run photos.`);
  }
  return photo;
};

// Gallery order and captions (captions double as alt text)
const GALLERY = [
  { slug: 'daisy-and-milo', caption: 'Daisy and Milo!' },
  { slug: 'me-playing-piano', caption: "Me playing piano, working on building my 'Elton Joe' persona..." },
  { slug: 'me-fishing', caption: 'Me fishing, but I never touch the fish. Joshua does all the hard work.' },
  { slug: 'music-with-dad', caption: 'I get my musical talent from my dad, and we love to jam out together!' },
  { slug: 'daisy-milo', caption: 'Daisy and Milo LOVE being outside!!!' },
  { slug: 'me-joshua-fishing', caption: 'Me and Joshua after an evening of fishing!' },
  { slug: 'me-josh-zoo', caption: 'We also LOVE going to the Zoo!' },
  { slug: 'daisy-milo-2', caption: 'Milo always has to be near his sister Daisy...' },
  { slug: 'me-josh-fishing', caption: 'We love going to different parks nearby to fish in different spots!' },
  { slug: 'me-josh-fishing-2', caption: "I promise we do actually catch fish and don't just pose for pictures near water..." }
];

export const galleryPhotos = GALLERY.map(({ slug, caption }) => {
  const { src, width, height, srcSet } = getPhoto(slug);
  return { key: slug, src, width, height, srcSet, alt: caption, caption };
});

// Portraits: src plus a srcSet string for <img srcSet>
const portrait = (slug) => {
  const { src, srcSet } = getPhoto(slug);
  return { src, srcSet: srcSet.map((variant) => `${variant.src} ${variant.width}w`).join(', ') };
};

export const portraits = {
  headshot: portrait('me-headshot'),
  sunglasses: portrait('me-sunglasses'),
  noSunglasses: portrait('me-no-sunglasses')
};
